// Brandschutzplanung structured by the SIA 108:2014 phases. Checklist items paraphrase the VKF Brandschutz-
// vorschriften 2015 (Brandschutznorm 1-15 and the Brandschutzrichtlinien 10-15 … 28-15, Stand 01.01.2017);
// `ref` names the article or clause to look up. The HLKS-specific items (BSR 24-15, 25-15, 18/19-15 …) are
// defined once in the Heizung / Lüftung / Sanitär phases (sections flagged `fire`) and mirrored here: the
// Brandschutz pages show them with the state of the trade plan and write back to it.

import { type HeatingPhase, type HeatingSection, heatingPhases } from "@/lib/heating/phases";
import type { HeatingPlan } from "@/lib/heating/plan-schema";
import { type Phase as VentilationPhase, type PhaseSection as VentilationSection, phases as ventilationPhases } from "@/lib/kwl/phases";
import type { PlanData as VentilationPlan } from "@/lib/kwl/plan-schema";
import { type CheckState, isHandled, type L10n, type PlanChecklistItem } from "@/lib/planning";
import { type SanitaryPhase, type SanitaryPhaseSection, sanitaryPhases } from "@/lib/sanitary/phases";
import type { SanitaryPlan } from "@/lib/sanitary/plan-schema";

import type { FireParams, FirePlan } from "./plan-schema";

export type FireItem = PlanChecklistItem<FireParams>;
export type FireTrade = "heating" | "ventilation" | "sanitary";
/** Route segment of each trade below /projekte/[id]. */
export const tradePath = { heating: "heizung", ventilation: "lueftung", sanitary: "sanitaer" } as const satisfies Record<FireTrade, string>;
type VentilationChecklist = Extract<VentilationSection, { kind: "checklist" }>;
export type FireSection =
  | { kind: "checklist"; key: string; title: L10n; items: FireItem[] }
  | { kind: "mirror"; trade: "heating"; key: string; title: L10n; items: HeatingSection["items"] }
  | { kind: "mirror"; trade: "ventilation"; key: string; title: L10n; items: VentilationChecklist["items"] }
  | { kind: "mirror"; trade: "sanitary"; key: string; title: L10n; items: SanitaryPhaseSection["items"] };
export type FirePhase = { code: string; sia108: string; title: L10n; goal: L10n; sections: FireSection[] };

/** The four plans the Brandschutz pages read (own criteria and checks plus the mirrored trades). */
export type FirePlans = {
  fire: FirePlan;
  heating: HeatingPlan;
  ventilation: VentilationPlan;
  sanitary: SanitaryPlan;
};

type P = FireParams;
type Cond = (p: P) => boolean;

const i = (id: string, ref: string, de: string, fr: string, it: string, when?: Cond): FireItem => ({ id, ref, text: { de, fr, it }, when });
const list = (key: string, title: L10n, items: FireItem[]): FireSection => ({ kind: "checklist", key, title, items });
const t = (de: string, fr: string, it: string): L10n => ({ de, fr, it });

const all = (...conds: Cond[]): Cond => (p) => conds.every((c) => c(p));
const any = (...conds: Cond[]): Cond => (p) => conds.some((c) => c(p));
const lowHeight: Cond = (p) => p.height === "low";
const mediumHeight: Cond = (p) => p.height === "medium";
const highRise: Cond = (p) => p.height === "highRise";
const usage = (u: P["usages"][number]): Cond => (p) => p.usages.includes(u);
const office = usage("office");
const school = usage("school");
const retail = usage("retail");
const hospitalityA = usage("hospitalityA");
const hospitalityB = usage("hospitalityB");
const hospitalityC = usage("hospitalityC");
const assembly = usage("assembly");
const industry = usage("industry");
const parking = usage("parking");
const renovation: Cond = (p) => p.construction === "renovation";
const sprinklerConcept: Cond = (p) => p.concept === "sprinkler";
const performance: Cond = (p) => p.concept === "performance";
const qssAbove = (level: number): Cond => (p) => p.qss > level;
const qsRole: Cond = (p) => p.qsRole;
const timber: Cond = (p) => p.timber;
const sprinkler: Cond = (p) => p.sprinkler || p.concept === "sprinkler";
const fireAlarm: Cond = (p) => p.fireAlarm;
const smokeExtraction: Cond = (p) => p.smokeExtraction !== "none";
const mechanicalSmoke: Cond = (p) => p.smokeExtraction === "mechanical";
const lightning: Cond = (p) => p.lightning;
const safetyLighting: Cond = (p) => p.safetyLighting;
const lifts: Cond = (p) => p.lifts;

/** Sections of a trade phase that carry fire-protection items (flagged `fire` in the trade definitions). */
const mirrored = (code: string): FireSection[] => {
  const heating = heatingPhases.find((p: HeatingPhase) => p.code === code)?.sections.filter((s) => s.fire) ?? [];
  const ventilation =
    ventilationPhases.find((p: VentilationPhase) => p.code === code)?.sections.filter((s): s is VentilationChecklist => s.kind === "checklist" && !!s.fire) ?? [];
  const sanitary = sanitaryPhases.find((p: SanitaryPhase) => p.code === code)?.sections.filter((s) => s.fire) ?? [];
  return [
    ...heating.map((s): FireSection => ({ kind: "mirror", trade: "heating", key: `heating.${s.key}`, title: s.title, items: s.items })),
    ...ventilation.map((s): FireSection => ({ kind: "mirror", trade: "ventilation", key: `ventilation.${s.key}`, title: s.title, items: s.items })),
    ...sanitary.map((s): FireSection => ({ kind: "mirror", trade: "sanitary", key: `sanitary.${s.key}`, title: s.title, items: s.items })),
  ];
};

