export const firePhases: FirePhase[] = meta.map((m) => ({ ...m, sections: [...(own[m.code] ?? []), ...mirrored(m.code)] }));

export const findFirePhase = (code: string) => firePhases.find((p) => p.code === code);

export type FireSectionItem = { id: string; ref: string; text: L10n; applies: boolean; state: CheckState | undefined };

/** Items of a section with applicability and state, read from the plan that owns them. */
export function fireSectionItems(section: FireSection, plans: FirePlans): FireSectionItem[] {
  const map = <Q>(items: PlanChecklistItem<Q>[], params: Q, checks: Record<string, CheckState>): FireSectionItem[] =>
    items.map((item) => ({ id: item.id, ref: item.ref, text: item.text, applies: !item.when || item.when(params), state: checks[item.id] }));
  if (section.kind === "checklist") return map(section.items, plans.fire.params, plans.fire.checks);
  switch (section.trade) {
    case "heating":
      return map(section.items, plans.heating.params, plans.heating.checks);
    case "ventilation":
      return map(section.items, plans.ventilation.params, plans.ventilation.checks);
    case "sanitary":
      return map(section.items, plans.sanitary.params, plans.sanitary.checks);
  }
}

/** Progress of a Brandschutz phase over own and mirrored items. */
export function fireProgress(phase: FirePhase, plans: FirePlans) {
  const items = phase.sections.flatMap((s) => fireSectionItems(s, plans)).filter((item) => item.applies);
  return { done: items.filter((item) => isHandled(item.state)).length, total: items.length };
}

/** Plan that holds the state of a section's items. */
export const sectionTrade = (section: FireSection): FireTrade | "fire" => (section.kind === "mirror" ? section.trade : "fire");
